Here is an example code in Arduino that demonstrates the process of calibrating a DHT22 temperature and humidity sensor:
```c
#include <DHT.h>

#define DHT_PIN 2  // Replace with the pin connected to the DHT22 sensor

DHT dht(DHT_PIN, DHT11);  // Initialize the DHT sensor

const int numReadings = 50;  // Number of readings to take
const int calibrationDelay = 5000;  // Delay between readings (in ms)

int temperatureOffset = 0;
int humidityOffset = 0;

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  int temperature = dht.readTemperature();
  int humidity = dht.readHumidity();

  if (isnan(temperature) || isnan(humidity)) {
    Serial.println("Error reading sensor!");
    delay(5000);
  } else {
    // Calculate the offset between the sensor readings and your known values
    int tempOffset = calculateTemperatureOffset(temperature);
    int humidOffset = calculateHumidityOffset(humidity);

    // If the offset is different from the previous offset, update the calibration values
    if (abs(tempOffset - temperatureOffset) > 0.5 || abs(humidOffset - humidityOffset) > 0.1) {
      temperatureOffset = tempOffset;
      humidityOffset = humidOffset;
      Serial.print("Calibration updated: ");
      Serial.print("Temperature offset: ");
      Serial.print(temperatureOffset);
      Serial.print("°C");
      Serial.print(" Humidity offset: ");
      Serial.print(humidityOffset);
      Serial.println("%");
    }

    // Display the calibrated values
    int calibratedTemperature = temperature + temperatureOffset;
    int calibratedHumidity = humidity + humidityOffset;
    Serial.print("Calibrated values: ");
    Serial.print(calibratedTemperature);
    Serial.print("°C / ");
    Serial.print(calibratedHumidity);
    Serial.println("%");
  }

  delay(calibrationDelay);
}

// Function to calculate the temperature offset based on your known temperature value
int calculateTemperatureOffset(int temperature) {
  // Insert your known temperature value here
