**Step 1: Create a context**

First, create a context using the ` createContext` hook:
```js
import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedback, setFeedback] = useState({
    sections: [
      { id: 1, title: 'General Feedback' },
      { id: 2, title: 'Teaching Methods' },
      { id: 3, title: 'Course Material' },
    ],
    questions: [
      { id: 1, sectionId: 1, text: 'How would you rate the overall course?' },
      { id: 2, sectionId: 1, text: 'What did you find most helpful about the course?' },
      { id: 3, sectionId: 2, text: 'How would you rate the teaching methods?' },
      // ...
    ],
    answers: {},
  });

  const addAnswer = (questionId, answer) => {
    setFeedback((prevFeedback) => ({
      ...prevFeedback,
      answers: { ...prevFeedback.answers, [questionId]: answer },
    }));
  };

  return (
    <FeedbackContext.Provider value={{ feedback, addAnswer }}>
      {children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackProvider, FeedbackContext };
