const canvas = document.getElementById('pendulum-canvas');
const ctx = canvas.getContext('2d');
const initialAngle = 45; // degrees
let angle = initialAngle * Math.PI / 180; // convert to radians
let velocity = 0;
let time = 0;

function drawPendulum() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.moveTo(canvas.width / 2, canvas.height / 2);
  ctx.lineTo(canvas.width / 2 + Math.sin(angle) * (canvas.width / 2), canvas.height / 2 - Math.cos(angle) * (canvas.height / 2));
  ctx.stroke();
}

function update() {
  // Calculate new angle and velocity using simple harmonic motion
  angle += velocity;
  velocity -= 0.1 * Math.sin(angle); // simulate gravity (0.1 is a constant)

  // Check if pendulum has stopped oscillating
  if (Math.abs(velocity) < 0.01) {
    velocity = 0;
  }

  // Create a new frame
  drawPendulum();
  time++;
  requestAnimationFrame(update);
}

function releasePendulum() {
  angle = initialAngle * Math.PI / 180; // convert to radians
  velocity = 0;
  update();
}

document.getElementById('release-button').addEventListener('click', releasePendulum);

update();
