```go
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-lambda-go/lambda"
	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	log.Println("Deleting EBS Snapshots...")

	sess, err := session.NewSession(&aws.Config{Region: aws.String("your_region")}, nil)
	if err != nil {
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	daysToDelete := map[string]int{
		"yearly": 1,
		"monthly": 14,
		"daily":   10,
		"weekly":  4,
	}

	tagName := "backup_type"
	tagValue := "monthly" // default value

	// Get all EBS Snapshots with the specified tag
	snapshots, err := ec2Svc.DescribeSnapshots(&ec2.DescribeSnapshotsInput{
		Filter: []*ec2.Filter{
			{
				Name: aws.String("tag:backup_type"),
				Values: []*string{
					aws.String(tagValue),
				},
			},
		},
	})
	if err != nil {
		return nil, err
	}

	// Iterate over the snapshots and delete the ones that are older than the desired retention period
	for _, snapshot := range snapshots.Snapshots {
		snapShotId := *snapshot.SnapshotId
		backuptime := *snapshot.Tags[0].Value

		if backuptime == tagName {
			continue
		}

		if backuptime == "yearly" {
			/* Check Yearly Snapshots*/
			year, month := layout.Parse(backuptime).Unix()
			if time.Now().Unix() > year {

				DeleteSnapshot(ec2Svc, snapShotId)
			}
		} else if backuptime == "monthly" {
			/* Check Monthly Snapshots */
			// keep last 14 snapshots
			month := layout.Parse(backuptime).Date()
			if month.Month() == time.Now().Month() {
				DeleteSnapshot(ec2Svc, snapShotId)
			} else if len(snapshots.Snapshots) < 14 {
				DeleteSnapshot(ec2Svc, snapShotId)
			} else {
				snapshots.Snapshots = append(snapshots.Snapshots[:0], snapshots.Snapshots[14:]...)
			}

		} else if backuptime == "weekly" {
			/* Check Weekly Snapshots */
			// keep last 4 snapshots
			week := layout.Parse(backuptime).Week()
			if week == time.Now().Week() {
				DeleteSnapshot(ec2Svc, snapShotId)
			} else if len(snapshots.Snapshots) < 4 {
				DeleteSnapshot(ec2Svc, snapShotId)
			} else {
				snapshots.Snapshots = append(snapshots.Snapshots[:0], snapshots.Snapshots[4:]...)
			}
		} else if backuptime == "daily" {
			/* Check Daily Snapshots */
			// keep last 10 snapshots
			day := layout.Parse(backuptime).Date()
			if day == time.Now().Date() {
				DeleteSnapshot(ec2Svc, snapShotId)
			} else if len(snapshots.Snapshots) < 10 {
				DeleteSnapshot(ec2Svc, snapShotId)
			} else {
				snapshots.Snapshots = append(snapshots.Snapshots[:0], snapshots.Snapshots[10:]...)
			}

		}
	}

	return nil, nil
}

func DeleteSnapshot(ec2Svc *ec2.EC2, snapShotId string) {
	_, err := ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
		SnapshotId: aws.String(snapShotId),
	})
	if err != nil {
		log.Println(err)
	}
}

func main() {
	lambda.Start(handler)
}
