  <body>
    <h1>Round-Robin URL Router</h1>
    <script>
      // Set the base URL for the REST API
      const apiUrl = 'https://api.example.com/counter';

      // Initialize the counter value
      let counterValue = 0;

      // Get the initial counter value from the REST API
      fetch(apiUrl)
        .then(response => response.json())
        .then(data => counterValue = data.value)
        .catch(error => console.error(error));

      // Define the 10 URLs to rotate
      const urls = [
        'https://example1.com',
        'https://example2.com',
        'https://example3.com',
        'https://example4.com',
        'https://example5.com',
        'https://example6.com',
        'https://example7.com',
        'https://example8.com',
        'https://example9.com',
        'https://example10.com'
      ];

      // Function to get the next URL in the round-robin sequence
      function getNextUrl() {
        const currentIndex = counterValue % urls.length;
        const nextUrl = urls[currentIndex];
        counterValue++;
        return nextUrl;
      }

      // Function to redirect to the next URL in the round-robin sequence
      function redirectToNextUrl() {
        const nextUrl = getNextUrl();
        window.location.href = nextUrl;
      }

      // Call the function to redirect to the next URL
      redirectToNextUrl();

      // Set a timer to call the function to redirect to the next URL every 5 seconds
      setInterval(redirectToNextUrl, 5000);
    </script>
  </body>
</html>
