using System;
using System.Net.Mail;
using System.Net;
using System.Collections.Generic;

namespace EmailSender
{
    class Program
    {
        static class MailSettings
        {
            public static readonly string[] EmailAccounts = new string[] { "email1@example.com", "email2@example.com", "email3@example.com" };
            public static readonly string[] EmailPasswords = new string[] { "password1", "password2", "password3" };
            public static readonly string SMTPServer = "smtp.example.com";
            public static readonly int SMTPPort = 587;
        }

        static void Main(string[] args)
        {
            List<string> subscribers = new List<string>();
            // Add your list of subscribers here
            for (int i = 0; i < 100; i++)
            {
                subscribers.Add($"subscriber{i}@example.com");
            }

            int currentIndex = 0;
            bool sendEmails = true;
            while (sendEmails)
            {
                for (int i = 0; i < subscribers.Count; i++)
                {
                    string subscriberEmail = subscribers[i];
                    string emailAccount = MailSettings.EmailAccounts[currentIndex];
                    string emailPassword = MailSettings.EmailPasswords[currentIndex];

                    using (var smtpClient = new SmtpClient())
                    {
                        smtpClient.Host = MailSettings.SMTPServer;
                        smtpClient.Port = MailSettings.SMTPPort;
                        smtpClient.SetDefaultCredentials();
                        smtpClient.Credentials = new NetworkCredential(emailAccount, emailPassword);

                        using (var mailMessage = new MailMessage())
                        {
                            mailMessage.From = new MailAddress(emailAccount);
                            mailMessage.To.Add(subscriberEmail);
                            mailMessage.Subject = "Test Email";
                            mailMessage.Body = "This is a test email";

                            smtpClient.Send(mailMessage);
                        }
                    }

                    currentIndex = (currentIndex + 1) % MailSettings.EmailAccounts.Length;
                }

                // Add a delay to avoid sending emails too quickly
                System.Threading.Thread.Sleep(1000);
            }
        }
    }
}
```
