int main(int argc, char** argv) {
    if (argc != 3) {
        std::cerr << "Usage: patcher <exe_file> <patch_file>" << std::endl;
        return 1;
    }

    std::ifstream exeFile(argv[1], std::ios::binary);
    if (!exeFile) {
        std::cerr << "Could not open executable file '" << argv[1] << "'" << std::endl;
        return 1;
    }

    std::ifstream patchFile(argv[2], std::ios::binary);
    if (!patchFile) {
        std::cerr << "Could not open patch file '" << argv[2] << "'" << std::endl;
        return 1;
    }

    uint32_t offset;
    exeFile.seekg(0x002D32CC, std::ios::beg); // seek to 0x002D32CC offset
    patchFile.read(reinterpret_cast<char*>(&offset), sizeof(uint32_t));
    exeFile.write(reinterpret_cast<char*>(&offset), sizeof(uint32_t));
    exeFile.seekp(0x002D32CC, std::ios::beg);
    exeFile.write(reinterpret_cast<char*>(patchFile.rdbuf()), sizeof(uint8_t)); // replace 0x75 with 0xEB

    exeFile.seekg(0x002D32CD, std::ios::beg); // seek to 0x002D32CD offset
    patchFile.read(reinterpret_cast<char*>(&offset), sizeof(uint32_t));
    exeFile.write(reinterpret_cast<char*>(&offset), sizeof(uint32_t));
    exeFile.seekp(0x002D32CD, std::ios::beg);
    exeFile.write(reinterpret_cast<char*>(patchFile.rdbuf()), sizeof(uint8_t)); // replace 0x47 with 0x42

    std::cout << "Patching complete." << std::endl;
    return 0;
}
