import { Injectable } from '@nestjs/common';
import * as jwt from 'jsonwebtoken';
import { discern } from 'fast-crypto';

@Injectable()
export class AuthService {
  async generateToken(user: any) {
    const payload = {
      sub: user.id,
      name: user.name,
      email: user.email,
    };

    const token = jwt.sign(payload, 'SecretKey123!', { expiresIn: '1h' });

    // Set cookie with JWT token
    this.setCookie(token, 'access_token', 'http://localhost:3000');

    return token;
  }

  setCookie(token: string, name: string, url: string) {
    document.cookie = `${name}=${token}; path=${url}; expires=Tue, 31 Dec 2099 23:59:59 GMT; secure; HttpOnly; SameSite=None`;
  }
}
